#!/usr/bin/env node
// bundle copy generated by scripts/sync-assets.mjs: main-guard keyed on CCO_HOOK_MAIN (see resources/entry/cco-hook-bundle.mjs)
/**
 * Install CCO's hooks into the project's .cursor/hooks.json (the IDE reads project hooks; hooks
 * declared by a plugin run in the CLI only). Entries run a small shim at .cursor/cco-hook.mjs (committed next to hooks.json)
 * that locates the installed plugin at runtime, so plugin updates never break the hooks and the
 * project can be moved or shared.
 *
 *   node scripts/cco-install-hooks.mjs --workspace . [--uninstall]
 */
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { PLUGIN_ROOT, parseArgs, readJsonSafe, writeJson, workspacePaths, ensureDir } from "./lib/common.mjs";

const MARKER = "cco-hook";

export function targetPath({ workspace }) {
  return workspacePaths(path.resolve(workspace)).hooksPath;
}

const SHIM_SOURCE = `#!/usr/bin/env node
// CCO hook shim (project-local): finds the installed cursor-ai-cost-optimizer plugin and runs its dispatcher.
// Generated by cco-init; safe to delete (re-run cco-init to recreate).
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { pathToFileURL, fileURLToPath } from "node:url";
import { spawnSync } from "node:child_process";

function candidates() {
  const out = [];
  if (process.env.CCO_PLUGIN_DIR) out.push(process.env.CCO_PLUGIN_DIR);
  const pinned = path.join(path.dirname(new URL(import.meta.url).pathname), "cco", "plugin-path.txt");
  try { out.push(fs.readFileSync(pinned, "utf8").trim()); } catch {}
  const plugins = path.join(os.homedir(), ".cursor", "plugins");
  out.push(path.join(plugins, "local", "cursor-ai-cost-optimizer"));
  try {
    const cache = path.join(plugins, "cache");
    for (const market of fs.readdirSync(cache)) {
      const mdir = path.join(cache, market);
      for (const name of fs.readdirSync(mdir)) {
        if (!name.startsWith("cursor-ai-cost-optimizer")) continue;
        const vdir = path.join(mdir, name);
        const versions = fs.readdirSync(vdir).map((v) => path.join(vdir, v)).filter((p) => fs.existsSync(path.join(p, "scripts", "cco-hook.mjs")));
        versions.sort((a, b) => fs.statSync(b).mtimeMs - fs.statSync(a).mtimeMs);
        out.push(...versions);
      }
    }
  } catch {}
  return out.filter((p) => p && fs.existsSync(path.join(p, "scripts", "cco-hook.mjs")));
}

let input = "";
try { input = fs.readFileSync(0, "utf8"); } catch {}
const plugin = candidates()[0];
const event = process.argv[2] || "";
if (!plugin) {
  // The plugin is gone (removed from Cursor, or this clone never had it). Stay a silent no-op, and after
  // 7 days of the plugin still being missing, strip our own hook entries and delete this shim so nothing lingers.
  try {
    const here = path.dirname(fileURLToPath(import.meta.url));
    const marker = path.join(here, "cco", "state", "plugin-missing.json");
    let since = Date.now();
    try { since = Number(JSON.parse(fs.readFileSync(marker, "utf8")).since) || since; } catch { fs.mkdirSync(path.dirname(marker), { recursive: true }); fs.writeFileSync(marker, JSON.stringify({ since })); }
    if (Date.now() - since > 7 * 24 * 60 * 60 * 1000) {
      const hooksFile = path.join(here, "hooks.json");
      const data = JSON.parse(fs.readFileSync(hooksFile, "utf8"));
      const hooks = {};
      for (const [ev, list] of Object.entries(data.hooks || {})) {
        const kept = (list || []).filter((e) => !String(e.command || "").includes("cco-hook"));
        if (kept.length) hooks[ev] = kept;
      }
      if (Object.keys(hooks).length) fs.writeFileSync(hooksFile, JSON.stringify({ ...data, hooks }, null, 2) + "\\n");
      else fs.unlinkSync(hooksFile);
      fs.unlinkSync(fileURLToPath(import.meta.url));
    }
  } catch {}
  process.stdout.write(JSON.stringify({ continue: true, permission: "allow" }) + "\\n");
  process.exit(0);
}
process.env.CCO_PLUGIN_ROOT = plugin;
try { fs.unlinkSync(path.join(path.dirname(fileURLToPath(import.meta.url)), "cco", "state", "plugin-missing.json")); } catch {}
try {
  const { dispatch } = await import(pathToFileURL(path.join(plugin, "scripts", "cco-hook.mjs")).href);
  process.stdout.write(await dispatch(event, input));
} catch {
  const res = spawnSync(process.execPath, [path.join(plugin, "scripts", "cco-hook.mjs"), event], { input, encoding: "utf8", timeout: 45000, env: { ...process.env, CCO_PLUGIN_ROOT: plugin } });
  process.stdout.write(res.stdout || (JSON.stringify({ continue: true, permission: "allow" }) + "\\n"));
}
`;

export function writeShim(workspace, pluginRoot = PLUGIN_ROOT) {
  const paths = workspacePaths(path.resolve(workspace));
  ensureDir(paths.ccoDir);
  try {
    fs.unlinkSync(path.join(paths.ccoDir, "cco-hook.mjs")); // pre-0.2 location
  } catch {}
  fs.writeFileSync(paths.shimPath, SHIM_SOURCE, "utf8");
  fs.writeFileSync(path.join(paths.ccoDir, "plugin-path.txt"), `${pluginRoot}\n`, "utf8");
  return paths.shimPath;
}

/** Hook commands are relative to the project root (Cursor runs project hooks with cwd = workspace). */
export function buildEntries(pluginRoot = PLUGIN_ROOT) {
  const template = readJsonSafe(path.join(pluginRoot, "hooks", "hooks.json")) || { hooks: {} };
  const out = {};
  for (const [event, entries] of Object.entries(template.hooks || {})) {
    out[event] = (entries || []).map((entry) => ({ ...entry, command: `node .cursor/cco-hook.mjs ${event}` }));
  }
  return out;
}

export function isOurs(entry) {
  return typeof entry?.command === "string" && entry.command.includes(MARKER);
}

export function mergeHooks(existing, ours) {
  const base = existing && typeof existing === "object" ? { ...existing } : {};
  const hooks = { ...(base.hooks || {}) };
  for (const [event, list] of Object.entries(hooks)) {
    hooks[event] = (Array.isArray(list) ? list : []).filter((entry) => !isOurs(entry));
  }
  for (const [event, list] of Object.entries(ours || {})) {
    hooks[event] = [...(hooks[event] || []), ...list];
  }
  for (const event of Object.keys(hooks)) {
    if (!hooks[event].length) {
      delete hooks[event];
    }
  }
  return { ...base, version: base.version || 1, hooks };
}

export function installHooks({ workspace, pluginRoot = PLUGIN_ROOT }) {
  const shim = writeShim(workspace, pluginRoot);
  const file = targetPath({ workspace });
  const entries = buildEntries(pluginRoot);
  writeJson(file, mergeHooks(readJsonSafe(file), entries));
  return { file, shim, events: Object.keys(entries) };
}

export function uninstallHooks({ workspace }) {
  const file = targetPath({ workspace });
  const existing = readJsonSafe(file);
  if (!existing) {
    return { file, removed: false };
  }
  const merged = mergeHooks(existing, {});
  if (!Object.keys(merged.hooks).length && Object.keys(merged).every((k) => k === "version" || k === "hooks")) {
    fs.unlinkSync(file);
    return { file, removed: true, deleted: true };
  }
  writeJson(file, merged);
  return { file, removed: true };
}

export function hooksInstalled({ workspace }) {
  const data = readJsonSafe(targetPath({ workspace }));
  return Boolean(data && Object.values(data.hooks || {}).some((list) => (list || []).some(isOurs)));
}

function main() {
  const args = parseArgs(process.argv.slice(2), { workspace: process.cwd(), uninstall: false });
  const workspace = String(args.workspace);
  const result = args.uninstall ? uninstallHooks({ workspace }) : installHooks({ workspace });
  console.log(JSON.stringify({ ok: true, ...result, pluginRoot: PLUGIN_ROOT }, null, 2));
}

if (process.env.CCO_HOOK_MAIN === "cco-install-hooks.mjs") {
  main();
}
